#include "game.hpp"
#include "strategy_workspace.hpp"
#include "json.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace hyperion;
namespace {
int checks=0;
void check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
bool near(double a,double b){return std::abs(a-b)<1e-6;}
nlohmann::json snapshot(const State& state){auto path=(std::filesystem::temp_directory_path()/"hyperion-planning-snapshot.json").string();std::string error;check(saveState(state,path,error),"snapshot saves");std::ifstream in(path);nlohmann::json data;in>>data;in.close();std::filesystem::remove(path);return data;}
}
int main(){try{
 Game g;g.ensureEconomy();g.s.mode=Mode::Ocean;g.s.activePlanet=2;g.s.depth=g.maxDepth()+30;g.s.battery=13;g.parkFlight(2,{3200,1800});g.s.mode=Mode::Ocean;g.s.flight.deployed=true;
 auto before=snapshot(g.s);auto forecast=g.outlook();check(forecast.warnings>=1&&near(forecast.pressureLoss,6.6),"briefing identifies exact one-hour pressure exposure");check(near(forecast.battery,17),"briefing calculates strategic battery recovery");check(g.orderHint("scan").find("5.0%")!=std::string::npos,"scan preview includes expenditure and recovery");check(!g.transferPlan("cockpit").available&&g.orderHint("cockpit").find("ascend")!=std::string::npos,"boarding preview requires a physical ascent from deep ocean");for(int i=0;i<240;i++){g.outlook(i%2?1:6);g.orderHint("wait");}check(snapshot(g.s)==before,"repeated briefing and hint queries cannot advance or mutate campaign");double hull=g.s.hull;g.endTurn();check(near(g.s.hull,hull-forecast.pressureLoss),"predicted pressure exposure agrees with actual resolution");
 g.s.battery=2;before=snapshot(g.s);check(g.orderHint("scan").find("requires 12")!=std::string::npos,"insufficient battery gets an actionable explanation");check(snapshot(g.s)==before,"disabled-order hint remains free");
 Game pilot;pilot.enterFlight();auto& f=pilot.s.flight;f.docked=false;f.dockedPort=-1;f.deployed=false;f.traffic.clear();hyperion::flight::Traffic enemy;enemy.kind=1;enemy.hostile=true;enemy.position=f.ship.position+f.ship.forward*50;f.traffic.push_back(enemy);pilot.system(pilot.s.currentStar);check(pilot.outlook().warnings>=1,"nearby live hostile appears in pre-turn risks");f.traffic[0].dead=true;check(pilot.outlook().warnings==0,"destroyed contacts do not produce stale threat warnings");
 Game economy;economy.ensureEconomy();economy.s.mode=Mode::System;auto& site=economy.s.economy.settlements.front();site.owner=0;site.built={};site.built[Habitat]=2;site.stock={};site.health=90;site.morale=70;site.loyalty=90;site.alerts=0;economy.s.economy.routes.clear();economy.s.economy.contracts.clear();std::string id=site.id,name=site.name;
 auto outlook=economy.outlook();check(outlook.warnings>=1&&std::any_of(outlook.items.begin(),outlook.items.end(),[&](const auto& item){return item.settlement==id&&item.text.find("food buffer")!=std::string::npos;}),"outpost food warning points to the actual settlement");
 before=snapshot(economy.s);for(int i=0;i<200;i++)economy.outlook(6);check(snapshot(economy.s)==before,"society briefing cannot spend stock or alter machinery");double hours=economy.s.hours;int turn=economy.s.turns;economy.waitHours(6);check(near(economy.s.hours,hours+1)&&economy.s.turns==turn+1,"new outpost crisis interrupts at one complete hour");check(economy.lastTurn.interruption.find(name)!=std::string::npos,"interrupted wait identifies the affected outpost");hours=economy.s.hours;economy.waitHours(6);check(near(economy.s.hours,hours+6),"an unchanged known crisis does not repeatedly cancel an explicit long wait");
 Game contract;contract.ensureEconomy();contract.s.mode=Mode::System;auto& issuer=contract.s.economy.settlements.front();Contract delivery;delivery.id="PLANNING-DEADLINE";delivery.settlement=issuer.id;delivery.deadline=.5;delivery.accepted=true;delivery.escrow=70;issuer.treasury-=70;contract.s.economy.contracts.push_back(delivery);check(contract.outlook().warnings>=1,"accepted deadline is visible before spending a turn");contract.waitHours(6);check(near(contract.s.hours,1)&&contract.s.turns==1&&contract.lastTurn.interruption.find("contract")!=std::string::npos,"accepted contract resolution interrupts a long wait");
 Game dock;dock.enterFlight();dock.s.flight.dockAt(dock.flightPort(dock.s.economy.settlements.front().id,true));dock.processFlightEvents();auto& office=dock.s.economy.settlements.front();Contract timed;timed.id="DOCKED-DEADLINE";timed.settlement=office.id;timed.deadline=dock.s.hours+.5;timed.accepted=true;timed.escrow=70;office.treasury-=70;dock.s.economy.contracts.push_back(timed);hours=dock.s.hours;turn=dock.s.turns;dock.waitHours(6);check(near(dock.s.hours,hours+1)&&dock.s.turns==turn&&!dock.lastTurn.strategic,"docked cockpit shift interruption does not invent strategic turns");check(dock.lastTurn.summary().find("Shift")!=std::string::npos&&!dock.lastTurn.interruption.empty(),"docked shift reports its own duration and cause rather than an older turn");
 Game nonPlayer;nonPlayer.ensureEconomy();nonPlayer.s.mode=Mode::System;for(auto& settlement:nonPlayer.s.economy.settlements)settlement.owner=1;nonPlayer.waitHours(6);check(near(nonPlayer.s.hours,6),"other factions' ordinary local crises do not interrupt player time");
 StrategyWorkspace ui;ui.clean=true;ui.panel=true;ui.tab=4;ui.scroll=211;ui.tabScroll[4]=211;ui.settlement="owned-outpost";ui.expanded={"construction","warehouse"};ui.marketGood=6;ui.factionChoice=3;ui.surfaceZoom=2.7;WorkspaceMemory memory;memory.board(ui);check(!ui.panel&&!ui.clean&&ui.scroll==0,"boarding clears the flight viewport");ui.tab=0;ui.scroll=15;ui.settlement="flight-port";ui.expanded={"combat"};ui.marketGood=1;memory.returnToStrategy(ui);check(ui.panel&&ui.clean&&ui.tab==4&&ui.scroll==211&&ui.settlement=="owned-outpost","strategy panel, scroll and selected settlement return exactly");check(ui.expanded.count("warehouse")&&ui.expanded.count("construction")&&!ui.expanded.count("combat")&&ui.marketGood==6&&ui.factionChoice==3&&ui.surfaceZoom==2.7,"strategy disclosures, selections and zoom survive flight UI edits");ui.scroll=99;memory.board(ui);ui.scroll=0;memory.returnToStrategy(ui);check(ui.scroll==99,"each handoff refreshes the saved workspace");memory.clear();ui.panel=false;ui.tab=1;memory.returnToStrategy(ui);check(!ui.panel&&ui.tab==1,"clearing memory prevents workspace leakage into a new campaign");
 std::cout<<"PASS: "<<checks<<" planning checks; read-only briefings, exact pressure/battery forecasts, live threats, colony and contract interrupts, and workspace restoration\n";return 0;
}catch(const std::exception& e){std::cerr<<"Planning failure after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
